'use strict';
/* 骊珠洞天 · 地名考据数据（key/tag/name/desc）与相关人物显示名
 * 来源：骊珠洞天古地图.html（村社级矢量舆图）的 POI 与 DESC 数据。
 * 说明：村社级矢量图尚未移植到小程序，此处先保留文字详目，功能不缺失。
 */
module.exports = {"CHARNAMES":{"chenpingan":"陈平安","qijingchun":"齐静春","ningyao":"宁姚","宋集薪":"宋集薪","李宝瓶":"李宝瓶","顾粲":"顾璨","刘羡阳":"刘羡阳","阮秀":"阮秀","李二":"李二","稚圭":"稚圭","蔡金简":"蔡金简","李槐":"李槐","林守一":"林守一","杨老头":"杨老头","魏檗":"魏檗","裴钱":"裴钱","崔东山":"崔东山","曹晴朗":"曹晴朗","周米粒":"周米粒","朱敛":"朱敛","姜尚真":"姜尚真","长命":"长命","郭竹酒":"郭竹酒","陈暖树":"陈暖树","崔瀺":"崔瀺","caoci":"曹慈","搬山猿":"搬山猿","魏晋":"魏晋","石柔":"石柔","刘灞桥":"刘灞桥","至圣先师":"至圣先师","lisan":"礼圣","亚圣":"亚圣","老秀才":"老秀才","baiye":"白也","郑居中":"郑居中","于玄":"于玄","火龙真人":"火龙真人","liujinglong":"刘景龙","贺小凉":"贺小凉","纳兰烧苇":"纳兰烧苇","xunyuan":"荀渊","余斗":"余斗","齐廷济":"齐廷济","陆芝":"陆芝"},"LIZHU":[{"key":"dongmen","tag":"东·门户","name":"东门","desc":"小镇最东的一排东倒西歪老旧栅栏，门口一个树墩。穿门后沿山路向上，山顶平台立两石柱（柱间水流转，其后景象难辨），再沿云梯向下约三十里即抵大骊；云梯四周云雾缭绕。外乡来小镇寻机缘者，须交看门人一袋金精铜钱（多则三十枚、少则二十枚），另携两枚信物锦囊，意即最多捞取两件宝物带出。"},{"key":"zhengdafeng","tag":"东·门户","name":"郑大风宅","desc":"小镇看门人郑大风的宅子，孤零零一座黄泥房，紧邻东门栅栏旁。郑大风即骊珠洞天阍者（守门人）。"},{"key":"lu","tag":"东·福禄街","name":"卢家","desc":"四姓十族中以卢氏为首。门口摆两尊等人高石狮子，狮口含一粒石球；门上有青铜狮子门首，贴彩绘财神像；内有一座临湖水榭。但在外，卢氏地位垫底——其主支当国执政的王朝被大骊两大边军联手覆灭，卢氏在东宝瓶洲地位已岌岌可危。"},{"key":"li","tag":"东·福禄街","name":"李家","desc":"后院角落一片紫竹林，为李宝瓶高祖所种。有一座李宝瓶以蛇胆石堆砌的水池，先养一只金黄色螃蟹，后又添一条金色过山鲫。李家后举家迁往大骊京城。"},{"key":"song","tag":"东·福禄街","name":"宋家","desc":"福禄街上李家再往前的大姓。四姓十族底蕴在于掌握多少口龙窑、管辖多少门户，决定每年供多少只本命瓷。"},{"key":"guandi","tag":"东·福禄街","name":"窑务督造官官邸","desc":"并不豪奢，占地不如卢李两姓宅子。衙署大堂外有广场，立一座牌坊正对大门，写一古体「岳」字（上丘下狱）。有一座戒备森严的库房，搁放烧造出的各类御用瓷器，验收无误即定期秘密送往京城。库房门口春联按例为坐镇圣人手笔；若是道家圣人坐镇一甲子内，还会就近取材，用桃叶巷桃木作春联底板。"},{"key":"zhao","tag":"东·福禄街","name":"赵家","desc":"在小镇不显山不露水，自诩为书香门第，书房古色古香。"},{"key":"lin","tag":"东·桃叶巷","name":"林家","desc":"不在四姓十族之列。林正诚是崔瀺亲自挑选出来的第二任阍者（守门人）。"},{"key":"wei","tag":"东·桃叶巷","name":"魏家","desc":"位于桃叶巷街角，名声不显。神仙坟一带魏家占地最多。"},{"key":"xie","tag":"东·桃叶巷","name":"谢家","desc":"北俱芦洲天君谢实祖宅，靠着一对香火小人维持家风数百年，勉强保住香火子嗣。"},{"key":"zisunhuai","tag":"东·福禄街","name":"子孙槐","desc":"在李宋两家大宅交界处的外墙，生长一棵槐树，与小镇中心的老槐一脉相承，被唤作子孙槐。"},{"key":"lipingxiang","tag":"西","name":"泥瓶巷","desc":"小镇西边住着的都是穷人，泥瓶巷即在此处，是小镇最为狭窄逼仄的巷弄之一，家家户户黄土院墙都很低矮。"},{"key":"lier","tag":"西·泥瓶巷","name":"李二家","desc":"位于小镇最西边。如今李二去往北俱芦洲，钥匙交给了陈暖树，宅院依旧干净整洁。"},{"key":"chenpingan","tag":"西·泥瓶巷","name":"陈平安祖宅","desc":"陈平安的祖宅，在泥瓶巷中。主角陈平安少年时于此长大，以烧瓷窑工、打草鞋为生。"},{"key":"songjixin","tag":"西·泥瓶巷","name":"宋集薪家·怀远堂","desc":"位于陈平安家右侧，在泥瓶巷属大户门庭，除悬挂匾额的大堂外还有左右偏房；大堂匾额为「怀远堂」，并无署名。宋集薪即小说开篇与陈平安同巷的「小少爷」。"},{"key":"cao","tag":"西·泥瓶巷","name":"曹家祖宅","desc":"大骊曹氏、剑仙曹曦的祖宅。牌匾中的香火小人被王朱吞食，因此破旧无人，以至于曾被袁真页踏破；院中有天井。"},{"key":"sanshanjiuhou","tag":"西·泥瓶巷","name":"三山九侯宅","desc":"万法宗师三山九侯先生曾在骊珠洞天游历，便住在泥瓶巷，位于陈平安祖宅隔壁。骊珠洞天的格局正由三山九侯先生精心布置。"},{"key":"wumingxiang","tag":"西·泥瓶巷","name":"无名小巷","desc":"从西边泥瓶巷可由此抄近路去往锁龙井。光线阴暗，比泥瓶巷更狭窄逼仄，身材稍高的青壮男子走入其中茅檐低于眉，只能低头而行，抬头便额头触檐；小巷不长，两壁对峙几要夹身。巷口处有口小水井，井口小且水浅。"},{"key":"laohuai","tag":"中·市井","name":"老槐树（祖宗槐）","desc":"过了牌坊没多远、位于小镇中心地带，一棵枝繁叶茂的老槐树，被小镇称作祖宗槐。树底下垫两块青石板作简易长凳，夏日百姓爱来乘凉，富户从井里捞出冰镇瓜果。老槐树叶即便离枝仍苍翠欲滴，每片叶中蕴含一份不同姓氏的祖宗福荫。骊珠洞天坠地后，老槐树被连根拔起。"},{"key":"daxue","tag":"中·市井","name":"大学士坊（螃蟹牌坊）","desc":"乡塾再往前，牌坊楼修十二根石柱，石柱底座为龙生九子九种异兽，之外是白虎、玄武、朱雀，当地人称为螃蟹牌坊。它相当于一份契约书——斩龙一役论功行赏最早在此签订盟约；也是镇剑楼与青童天君负责的飞升台。牌坊每面四块匾额、四字，共十六字：儒教「当仁不让」、道教「希言自然」、佛教「莫向外求」、兵家「气冲斗牛」，蕴含书写之人磅礴神意与四位圣人留在此地的一部分气数。写「当仁不让」者曾是当世书法第一人；「希言自然」由四位道教祖庭大真人分写。「冲」「斗」二字被齐静春赠予宁姚。骊珠洞天坠地后，其余字被大骊礼部以风雷笺拓碑，剥离精气神。"},{"key":"xiangshu","tag":"中·市井","name":"乡塾","desc":"距杏花巷再过一条街即是乡塾。内有一座不挂匾额的草堂书屋，后面有院子，北面矮小柴门通竹林，后院有下棋石桌。如更换圣人，有可能将乡塾改成道观或佛像，以甲子为限，由道人或僧人主持。齐静春曾在此讲学；陆沉的算命摊子设在乡塾附近。"},{"key":"jiulou","tag":"中·市井","name":"酒楼","desc":"小镇酒楼不大，共三层但只开放两层，此处是封姨的产业。窗外可看见牌坊「当仁不让」匾额，曾是小镇最高的建筑。"},{"key":"yangjia","tag":"中·市井","name":"杨家铺子","desc":"前店后坊格局，前院是药铺，后边有院子，正堂后门有回廊屋檐、天井。在杨老头眼中，天井内地面香火无数，每一炷香就是小镇某个人的香火，井底铺满香灰。历任圣人上任后，第二件事便是去杨家铺子打声招呼（早期宝瓶洲佛家势盛时，圣人往往不敢来，怕沾因果；如齐静春等未有人告知真相，故未能及时去）。杨老头即神道青童天君。"},{"key":"qilong","tag":"中·市井","name":"骑龙巷","desc":"骑道路狭窄，是一条斜坡，拥有一百二十二级台阶。草头铺子（贩卖杂物，最早是石家祖业，算骊珠洞天最早一处当铺，石家离开时半数古董珍玩留在铺子）与专门售糕点的压岁铺子，都是石嘉春家祖业；后石家搬去大骊京城，两间铺子在阮邛帮忙下辗转到了陈平安手上。巷内还有黄二娘桃花春烧酒铺。骑龙巷台阶顶部上边有相邻两口小水潭，被老人说成一双龙眼，水潭旁街道称火炉尖。"},{"key":"biandan","tag":"中·市井","name":"扁担巷","desc":"毛大娘包子家，肉包子尤其个大。另有喜事铺子——小镇白事铺子不少，喜事铺子却只有一个，掌柜是胡沣的爷爷，老人真名柴道煌；陆沉平时便借住在此处。"},{"key":"xinghua","tag":"中·市井","name":"杏花巷","desc":"此处巷道为黄泥路铺就。杏花巷深处是马家大宅，从内到外乃至院门口道路都比别家整洁；董水井家位于杏花巷，家中一口水井旁种有柳树；邹子曾在杏花巷摆糖葫芦摊子。"},{"key":"tiesuo","tag":"中·市井","name":"铁锁井","desc":"杏花巷一口水井，名叫铁锁井，一根粗如青壮手臂的铁链垂挂井口内。这条铁锁曾是成功束缚住世间最后一条真龙的一根缚妖索。此地规矩：「拽铁锁出井口者，每出一尺，折寿一年」。铁锁井也是真龙王朱的一口生气所在，能让她与外界天地相通；水井内有一座小洞天，地盘不大，适宜蛟龙之属、水泽精怪修行。后被大骊王朝封禁，百姓不得靠近汲水。小镇最后一次对外乡人开放时，锁链被姜韫带走。"},{"key":"erlang","tag":"中·市井","name":"二郎巷","desc":"紧挨着杏花巷。二郎巷与杏花巷没住大富大贵人家，比上不足比下绰绰有余。袁家祖宅大门贴两张崭新彩绘门神（一持短戟银甲、金鸡独立作金刚怒目状），不大却精致，头顶开方正天井、地上凿水池、通风极好，二楼设美人靠。胡沣家距离大骊上柱国袁氏祖宅不远。"},{"key":"qingniu","tag":"南·小镇外","name":"青牛背","desc":"出小镇往南，位于廊桥三十步外的溪畔。青色石崖，能站十多人，表面坑坑洼洼，以前小镇孩子来此凫水摸鱼各有挑选好的「座位」。本是一块上古月宫镜，如炼化得当，会是件半仙兵。"},{"key":"longxuxi","tag":"南·水系","name":"龙须溪","desc":"源头在西边大山中，为东南流向。廊桥附近水位多及膝，稍高处及腰，偶有人等高小水坑。小镇水源只有这一条。最早是条小溪涧，名浯溪；早年的浯溪陈氏，曾是骊珠洞天的头等大姓。龙须溪与小镇主街，被堪舆家视为隐显的两条「龙须」。"},{"key":"langqiao","tag":"南·小镇外","name":"廊桥·风生水起","desc":"位于小镇外南边，前身是一座横跨小溪的石拱桥。后大骊为求国祚绵长、国势风生水起，由宋煜章奉命在石拱桥外包裹一层木制廊桥，主要梁柱木头来自西边大山。廊桥悬一块金字匾额，四字极大——「风生水起」。建造时此地埋入一只等人高的大瓷罐，罐中葬着凄惨枉死的大骊宋氏龙子龙孙。廊桥下偶有成群鲤鱼（红青两色，曾有一条金色）；老剑条悬挂桥下，被圣人用来镇压锁龙井出口（即桥底碧绿深潭），防龙气流溢过快将小洞天撑破。小镇三千年来不管发多大洪水，龙须溪最高水位从未高过老剑条剑尖。骊珠洞天下坠后，恢复成老旧石拱桥。（注意：锁龙井即桥底那口碧绿深潭，囚着真龙残魂所化的骊珠；它与杏花巷的「铁锁井」并非一处——铁锁井中铁链乃缚妖索，系真龙王朱的一口生气所在，二者不可混淆。）"},{"key":"tiejiang","tag":"南·小镇外","name":"阮家铁匠铺","desc":"廊桥再走三四里路的溪畔，是阮家父女开办的铁匠铺，搭建黄泥屋和茅舍七八栋。打造有七口水井，井口留轱辘架子和围栏。此地土壤为火性土最后一种，按姚老头说法叫「七月流火壤」，土性自行转温凉、可塑性强。七口水井除蕴含七元解厄、承担一些佛家因果外，实与真龙尸骸遥遥呼应，是争珠之势（压胜之意更多）。洞天坠地后形势翻转，加大骊龙泉剑宗选的几座西边大山为阵眼，牵引气运反哺祖师堂所在神秀山。"},{"key":"xiaomiao","tag":"南·小镇外","name":"小庙","desc":"小镇南边黄泥小路，两侧是百姓稻田庄稼地，小路半道有座破败白墙黑瓦小庙，供百姓歇脚。庙内破败墙壁满是稚童炭笔涂鸦，大多是人名，低处斑驳不清或被人涂抹，高些处清晰可见：宋集薪、稚圭、赵繇、谢实、曹曦……刘羡阳和陈平安、顾粲三人的名字聚在左上角最高处。小庙里头写上名字的小镇孩子大多陨落，活下来的无一例外都是雄踞一方的豪杰枭雄（如谢实、曹曦）。杨老头如收租般，后来把小庙搬走。"},{"key":"fumu","tag":"南·小镇外","name":"陈平安父母坟","desc":"位于小庙再往南一处小山岭的半山腰，周围是多年不种庄稼的荒芜田地。"},{"key":"laoliushu","tag":"南·小镇外","name":"老柳树","desc":"位于出小镇的南下线路上的一棵老柳树。"},{"key":"shenxianfen","tag":"南·小镇外","name":"神仙坟","desc":"位于小镇东南方向。人迹罕至，周围是一座座早已无后人祭拜的坟茔，以及破败不堪的泥塑神像。有一尊五彩泥塑神像为披甲神人，大髯，铠甲铮铮、鳞片连绵，甲片边缘饰两条珠线、联珠颗粒饱满；神像踩踏在一座四方斩龙台上，《撼山》谱中的剑炉可能脱胎于此神像。骊珠洞天坠地后此处神像皆炸裂；后大骊朝廷出资修建为规格很高的武庙。三尊神像「肚内」既有市井铜钱，又有金精供养钱。"},{"key":"laocishan","tag":"北·小镇外","name":"老瓷山","desc":"位于小镇外北边，堆积着历朝历代被督造官亲笔判定为残次品的瓷器碎片；小镇本命瓷的碎片也在此处。"},{"key":"longyao","tag":"北·小镇外","name":"龙窑（三十余口）","desc":"除小镇东边外，小镇共有三十几座烧造瓷器的龙窑。它们建在那条真龙尸骸之上，以一处脊柱关键窍穴打造窑口，故每座龙窑烧造的本命瓷先天身负不同本命神通（如文昌窑、武隆窑、冲霄窑、拱璧窑、宝溪窑等）。龙窑号称千年窑火不熄，对于真龙王朱来说宛如油锅业火，不断灼烧其魂魄，亦压制人间蛟龙气运。此等布置与寻常堪舆多为对冲，却以天理压地理。东边没有龙窑、也没有田地。"},{"key":"xibiandashan","tag":"西·群山","name":"西边大山（六十二峰）","desc":"小镇西边群山，总计六十二座山头，早年陆陆续续被朝廷派来的督造官下令变成一座座封禁之山。原著明载其名者十四座：真珠山（骊珠所在·沂山）、披云山（最高峰·最神圣·北岳）、神秀山（天开神秀）、远幕峰（云海·千年古松）、黄湖山（山腰小湖·蟒蛇泓下）、仙草山（草木精魅）、地真山（远幕峰一带早年几被掏空）、挑灯山（神秀山西·瀑布深潭）、横槊峰（神秀山北·掎角之势）、灯芯台、宝箓山（占地极大·规模仅次披云神秀）、牛角山（临近神秀·敦厚）、梧桐山（隔宝箓牛角与神秀相邻）、彩云峰（小而高·风景秀美）。其余山头原著未赋专名，图上不臆造。小镇到挑灯山、横槊峰一带往返最少半月、最多一月。"},{"key":"zhenzhu","tag":"西·大山","name":"真珠山（沂山）","desc":"在窑务督造署官衙档案上记载叫沂山，位于小镇和西边大山接壤处，是真龙所衔「骊珠」所在，土味最全。入山先杂草丛生，后一片竹林。"},{"key":"piyun","tag":"西·大山","name":"披云山","desc":"西边大山最高峰，亦为骊珠洞天最为神圣之地（人称北岳），山势宏伟。"},{"key":"shenxiu","tag":"西·大山","name":"神秀山","desc":"高度仅次于披云山，有一面陡峭山壁刻四个大字——「天开神秀」。挑灯山、横槊峰与其呈掎角之势。"},{"key":"yuanmu","tag":"西·大山","name":"远幕峰","desc":"云海比落魄山稍胜一筹；有一座极高崖壁，有棵至少千年的古松，松间藤接树连壁，蜿蜒如大螈。"},{"key":"huanghu","tag":"西·大山","name":"黄湖山","desc":"半山腰有一座小湖泊，远观湖水泛黄、近看极清澈。盘踞着一条井口粗细的蟒蛇泓下，在与小泥鳅的「争水之战」中落败。"},{"key":"xiancao","tag":"西·大山","name":"仙草山","desc":"只比真珠山大上一筹，山势矮小但草木格外茂盛、参天大树颇多，是群山中唯一一座有望诞生草木精魅的风水宝地（只惜地方太小，即便出现一位，根脚品相也不会太好）。"},{"key":"dizhen","tag":"西·大山","name":"地真山","desc":"早年和远幕峰这一带几座山峰，几乎已被掏空采掘，一直到真珠山一带才有所好转。"},{"key":"tiaodeng","tag":"西·大山","name":"挑灯山","desc":"位于神秀山西方，隔着约莫十余里路。山中有一条大瀑布，瀑布之下有深潭。"},{"key":"hengshuo","tag":"西·大山","name":"横槊峰","desc":"位于神秀山北方，隔着约莫十余里路。与挑灯山、神秀山呈掎角之势，如同三尊巨人各立一方。小镇往返此地一带，最少半月、最多一月。"},{"key":"dengxin","tag":"西·大山","name":"灯芯台","desc":"与神秀山、黄湖山、宝箓山、彩云峰、仙草山同处「一峰两山」周围百里之内；灯芯台为其中较大的山头之一。"},{"key":"baolu","tag":"西·大山","name":"宝箓山","desc":"占地极大，在六十余座山头中名列前茅，且非空架子；云深山高水长，规模仅次于披云山与神秀山。陈平安曾买下此山。"},{"key":"niujiao","tag":"西·大山","name":"牛角山","desc":"临近神秀峰，山势不高、敦厚。"},{"key":"wutong","tag":"西·大山","name":"梧桐山","desc":"和神秀山之间，隔着宝箓山与牛角山。"},{"key":"caiyun","tag":"西·大山","name":"彩云峰","desc":"与仙草山、黄湖山、灯芯台、宝箓山同处「一峰两山」周围。山头较小而高、风景秀美（陈平安曾买下三座山头：仙草山小、宝箓山大、彩云峰高）。"}]};
